const webhookData = $('Webhook POST - Recibir Seleccion').first().json;
const selectedWorkflows = webhookData.body.workflows || [];

const qaWorkflows = $input.all().map(item => item.json);

if (!selectedWorkflows || selectedWorkflows.length === 0) {
  return [];
}

const workflowsToDeploy = qaWorkflows.filter(wf => 
  selectedWorkflows.includes(wf.id)
);

console.log(`Workflows seleccionados para desplegar: ${workflowsToDeploy.length}`);

return workflowsToDeploy.map(wf => ({ json: wf }));

// Obtener todos los workflows que llegan al nodo
const inputWorkflows = $input.all().map(item => JSON.parse(JSON.stringify(item.json)));

function removeEmojis(str) {
  return str
    .replace(/[\u{1F000}-\u{1FFFF}]/gu, '')
    .replace(/[\u{2600}-\u{26FF}]/gu, '')
    .replace(/[\u{2700}-\u{27BF}]/gu, '')
    .replace(/[\u{FE00}-\u{FE0F}]/gu, '')
    .replace(/[\u{1F900}-\u{1F9FF}]/gu, '')
    .replace(/[\u{1F300}-\u{1F5FF}]/gu, '')
    .replace(/[\u{1F680}-\u{1F6FF}]/gu, '')
    .replace(/[\u{1F1E0}-\u{1F1FF}]/gu, '')
    .trim()
    .replace(/\s+/g, ' ');
}

// Procesar cada workflow y devolver un item por cada uno
const processed = inputWorkflows.map(workflow => {
  const originalName = workflow.name;
  const originalQaId = workflow.id;

  // Eliminar campos problemáticos
  delete workflow.id;
  delete workflow.createdAt;
  delete workflow.updatedAt;
  delete workflow.versionId;
  delete workflow.error;
  delete workflow.shared;
  delete workflow.triggerCount;
  delete workflow.isArchived;

  workflow.name = removeEmojis(workflow.name);
  workflow._originalQaId = originalQaId;
  workflow.active = false;

  console.log(`Preparado: ${originalName} → ${workflow.name}`);

  return { json: workflow };
});

return processed;

// Tomar todos los workflows preparados desde el nodo "Preparar Workflow Individual"
const qaWorkflows = $('Preparar Workflow Individual').all().map(it => {
  // clonar para no mutar el original
  return JSON.parse(JSON.stringify(it.json));
});

// Tomar todos los workflows existentes en Prod que devolvió "Verificar Workflows Existentes"
const prodWorkflows = $input.all().map(it => it.json || {});

// Normalize helper para comparar nombres (sin emojis, trim y case-insensitive)
function normalizeName(name) {
  if (!name) return '';
  return String(name)
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '') // quitar tildes combinantes
    .replace(/[\u{1F000}-\u{1FFFF}]/gu, '') // emojis
    .replace(/[\u{2600}-\u{26FF}]/gu, '')
    .replace(/[\u{2700}-\u{27BF}]/gu, '')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase();
}

// Mapear cada QA workflow y decidir operación comparando por nombre (y opcionalmente por otros criterios)
const output = qaWorkflows.map(qawf => {
  const targetName = qawf.name || '';
  const norm = normalizeName(targetName);

  // Buscar coincidencia en prod por nombre normalizado
  const existing = prodWorkflows.find(pw => {
    const pwName = pw.name || '';
    return normalizeName(pwName) === norm;
  });

  // Preparar el metadata que usarán nodos siguientes
  qawf._metadata = {
    existingWfId: existing ? existing.id : null,
    shouldUpdate: !!existing,
    workflowName: targetName,
    // opcionales: incluir info adicional de prod para depuración
    prodMatch: existing ? { id: existing.id, name: existing.name } : null
  };

  // También dejar una propiedad 'operation' útil para IF/Switch
  qawf.operation = existing ? 'update' : 'create';

  // Retornar item para que n8n procese uno por uno
  return { json: qawf };
});

return output;

// Campos permitidos en el workflow limpio
const allowedFields = [
  'name',
  'nodes',
  'connections',
  'active',
  'settings',
  'tags',
  'pinData',
  'staticData',
  'meta'
];

// Obtener todos los workflows de entrada
const items = $input.all();

// Procesar cada uno
const cleanedItems = items.map(item => {
  const dirtyWorkflow = item.json;
  const cleanWorkflow = {};

  allowedFields.forEach(field => {
    if (dirtyWorkflow[field] !== undefined) {
      cleanWorkflow[field] = dirtyWorkflow[field];
    }
  });

  // Mantener metadatos importantes si existen
  if (dirtyWorkflow._metadata) {
    cleanWorkflow._metadata = dirtyWorkflow._metadata;
  }

  // Log opcional (solo visible en la ejecución)
  console.log(`Workflow "${dirtyWorkflow.name}" limpiado. Campos originales: ${Object.keys(dirtyWorkflow).length}. Campos finales: ${Object.keys(cleanWorkflow).length}`);

  return { json: cleanWorkflow };
});

// Devolver todos los items limpios
return cleanedItems;

const webhookData = $('Webhook POST - Recibir Seleccion').first().json;
const selectedWorkflowsIds = webhookData.body.workflows || [];

// Obtener todos los workflows originales de QA con sus IDs
const qaWorkflows = $('Filtrar Workflows').all().map(item => ({
  qaId: item.json.id,
  name: item.json.name
}));

// Obtener todos los resultados de las operaciones (crear/actualizar)
const allResults = $input.all();

console.log('=== INICIO ANALISIS DE RESULTADOS ===');
console.log('Workflows seleccionados:', selectedWorkflowsIds.length);
console.log('Workflows QA originales:', qaWorkflows.length);
console.log('Resultados recibidos:', allResults.length);

// Crear un mapa de workflows desplegados exitosamente (por ID de producción)
const successfulDeployments = new Map();

allResults.forEach(item => {
  const json = item.json;

  // Si tiene ID de producción y no tiene error, es exitoso
  if (json.id && !json.error && !(json.statusCode >= 400)) {
    const qaId = json._originalQaId || null;
    const prodId = json.id;
    const wasUpdate = json.updatedAt && json.createdAt && json.updatedAt !== json.createdAt;

    successfulDeployments.set(prodId, {
      prodId: prodId,
      qaId: qaId,
      name: json.name,
      action: wasUpdate ? 'Actualizado' : 'Creado',
      status: 'success'
    });

    console.log(`✓ Exitoso: ${json.name} (Prod ID: ${prodId}, Accion: ${wasUpdate ? 'Actualizado' : 'Creado'})`);
  }
});

// Ahora crear el reporte completo
const workflowResults = qaWorkflows.map(qaWf => {
  // Buscar si este workflow fue desplegado exitosamente
  const deployment = Array.from(successfulDeployments.values()).find(d => 
    d.name === qaWf.name || d.qaId === qaWf.qaId
  );

  if (deployment) {
    return {
      name: deployment.name,
      id: deployment.prodId,
      status: 'success',
      error: null,
      action: deployment.action
    };
  } else {
    // No fue desplegado exitosamente, buscar el error
    const errorResult = allResults.find(item => {
      const json = item.json;
      return (json.error || json.statusCode >= 400) && 
             (json.name === qaWf.name || json._originalQaId === qaWf.qaId);
    });

    const errorMsg = errorResult ? 
      (errorResult.json.error?.message || errorResult.json.message || 'Error desconocido') :
      'No se pudo desplegar';

    console.log(`✗ Fallido: ${qaWf.name} - ${errorMsg}`);

    return {
      name: qaWf.name,
      id: null,
      status: 'error',
      error: errorMsg,
      action: 'Error'
    };
  }
});

const successfulWorkflows = workflowResults.filter(w => w.status === 'success').length;
const failedWorkflows = workflowResults.filter(w => w.status === 'error').length;
const createdWorkflows = workflowResults.filter(w => w.action === 'Creado').length;
const updatedWorkflows = workflowResults.filter(w => w.action === 'Actualizado').length;

const report = {
  timestamp: new Date().toISOString(),
  summary: {
    workflows: {
      selected: selectedWorkflowsIds.length,
      total: workflowResults.length,
      successful: successfulWorkflows,
      failed: failedWorkflows,
      created: createdWorkflows,
      updated: updatedWorkflows,
      successRate: workflowResults.length > 0 
        ? ((successfulWorkflows / workflowResults.length) * 100).toFixed(1)
        : '0'
    }
  },
  details: {
    workflows: workflowResults
  }
};

console.log('\n' + '='.repeat(60));
console.log('REPORTE FINAL');
console.log('='.repeat(60));
console.log(`Workflows Seleccionados: ${selectedWorkflowsIds.length}`);
console.log(`Workflows Procesados: ${workflowResults.length}`);
console.log(`Workflows Exitosos: ${successfulWorkflows}`);
console.log(`Workflows Fallidos: ${failedWorkflows}`);
console.log(`Workflows Creados: ${createdWorkflows}`);
console.log(`Workflows Actualizados: ${updatedWorkflows}`);
console.log('='.repeat(60));

return [{ json: report }];

