            font-size: 0.85em;
            color: #c53030;
            border-radius: 4px;
            font-family: monospace;
        }
        .actions { display: flex; gap: 15px; margin-top: 30px; }
        button, a.button {
            padding: 15px 30px;
            border: none;
            border-radius: 10px;
            font-size: 1.1em;
            font-weight: 600;
            cursor: pointer;
            transition: all 0.3s;
            text-decoration: none;
            display: inline-block;
            text-align: center;
        }
        .btn-primary {
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            flex: 1;
        }
        .btn-primary:hover {
            transform: translateY(-2px);
            box-shadow: 0 10px 20px rgba(102, 126, 234, 0.4);
        }
        .empty-state { text-align: center; padding: 30px; color: #a0aec0; }
        .info-box {
            background: #ebf8ff;
            border-left: 4px solid #3182ce;
            padding: 15px;
            margin-bottom: 20px;
            border-radius: 5px;
        }
        .info-box p { color: #2c5282; margin: 0; }
        .success-box {
            background: #f0fff4;
            border-left: 4px solid #48bb78;
            padding: 15px;
            margin-bottom: 20px;
            border-radius: 5px;
        }
        .success-box p { color: #22543d; margin: 0; }
        .error-box {
            background: #fff5f5;
            border-left: 4px solid #f56565;
            padding: 15px;
            margin-bottom: 20px;
            border-radius: 5px;
        }
        .error-box p { color: #742a2a; margin: 0; }
    </style>
</head>
<body>
    <div class="container">
        <h1>Despliegue Completado</h1>
        <p class="subtitle">Reporte generado el ${new Date(report.timestamp).toLocaleString('es-ES')}</p>

        ${report.summary.workflows.failed === 0 && report.summary.workflows.successful > 0 ? `
        <div class="success-box">
            <p><strong>Exito:</strong> Todos los workflows fueron desplegados correctamente.</p>
        </div>
        <div class="info-box">
            <p><strong>Nota:</strong> Los workflows fueron desplegados en estado <strong>INACTIVO</strong>. Activalos manualmente en Produccion despues de verificarlos.</p>
        </div>
        ` : report.summary.workflows.failed > 0 ? `
        <div class="error-box">
            <p><strong>Error:</strong> ${report.summary.workflows.failed} de ${report.summary.workflows.total} workflow(s) fallaron durante el despliegue. Revisa los detalles abajo para identificar los problemas.</p>
        </div>
        ` : ''}

        <div class="summary-cards">
            <div class="card">
                <div class="card-title">TOTAL WORKFLOWS</div>
                <div class="card-value">${report.summary.workflows.total}</div>
                <div class="card-subtitle">${report.summary.workflows.selected} seleccionados</div>
            </div>

            <div class="card success-card">
                <div class="card-title">EXITOSOS</div>
                <div class="card-value">${report.summary.workflows.successful}</div>
                <div class="card-subtitle">${report.summary.workflows.successRate}% exito</div>
            </div>

            ${report.summary.workflows.failed > 0 ? `
            <div class="card error-card">
                <div class="card-title">FALLIDOS</div>
                <div class="card-value">${report.summary.workflows.failed}</div>
                <div class="card-subtitle">Requieren atencion</div>
            </div>
            ` : ''}

            ${report.summary.workflows.created > 0 ? `
            <div class="card created-card">
                <div class="card-title">CREADOS</div>
                <div class="card-value">${report.summary.workflows.created}</div>
                <div class="card-subtitle">Nuevos workflows</div>
            </div>
            ` : ''}

            ${report.summary.workflows.updated > 0 ? `
            <div class="card updated-card">
                <div class="card-title">ACTUALIZADOS</div>
                <div class="card-value">${report.summary.workflows.updated}</div>
                <div class="card-subtitle">Workflows existentes</div>
            </div>
            ` : ''}
        </div>

        ${report.summary.workflows.failed > 0 && report.details.workflows.filter(w => w.status === 'error').length > 0 ? `
            <div class="details-section">
                <div class="section-title">Workflows Fallidos</div>
                <div class="items-list">
                    ${report.details.workflows.filter(w => w.status === 'error').map(wf => `
                        <div class="item error">
                            <div class="item-info">
                                <div class="item-name">
                                    ${wf.name}
                                </div>
                                <div class="item-meta">
                                    ${wf.id ? `ID: <span class="item-id">${wf.id}</span>` : 'ID no disponible'}
                                </div>
                                ${wf.error ? `<div class="error-message">${wf.error}</div>` : ''}
                            </div>
                            <span class="status-badge error">
                                Fallo
                            </span>
                        </div>
                    `).join('')}
                </div>
            </div>
        ` : ''}

        ${report.details.workflows.filter(w => w.status === 'success').length > 0 ? `
            <div class="details-section">
                <div class="section-title">Workflows Exitosos</div>
                <div class="items-list">
                    ${report.details.workflows.filter(w => w.status === 'success').map(wf => `
                        <div class="item success">
                            <div class="item-info">
                                <div class="item-name">
                                    ${wf.name}
                                    ${wf.action !== 'Error' && wf.action !== 'Desconocido' ? `<span class="action-badge ${wf.action === 'Actualizado' ? 'updated' : 'created'}">${wf.action}</span>` : ''}
                                </div>
                                <div class="item-meta">
                                    ${wf.id ? `ID: <span class="item-id">${wf.id}</span>` : 'ID no disponible'}
                                </div>
                            </div>
                            <span class="status-badge success">
                                Exitoso
                            </span>
                        </div>
                    `).join('')}
                </div>
            </div>
        ` : ''}

        ${report.details.workflows.length === 0 ? `
            <div class="empty-state">
                <h3>No se desplegaron workflows</h3>
                <p>No se seleccionaron workflows para desplegar.</p>
            </div>
        ` : ''}

        <div class="actions">
            <button class="button btn-primary" onclick="window.location.reload()">
                Realizar Otro Despliegue
            </button>
        </div>
    </div>
</body>
</html>
`;

return [{ json: { html } }];

